/* Meridian personal dashboard. Plain JS, no third-party scripts or analytics. */
'use strict';
const $=s=>document.querySelector(s);
let model=null, current='overview', projectTab='plan', pollBusy=false, modalSpec=null;
let stateTag=null,pollTimer=null,analyticsDays=7,analyticsProject='all';
const goalExpanded={};
const labels={latitude:'Latitude',longitude:'Longitude',sundial:'Sundial'};
const iconPaths={
 overview:'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="8" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/><rect x="13" y="13" width="8" height="8" rx="1.5"/>',
 activity:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',
 chart:'<path d="M3 3v18h18"/><path d="m7 16 4-5 4 2 5-7"/>',
 note:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/>',
 settings:'<path d="M12 3v3m0 12v3m9-9h-3M6 12H3m15.4-6.4-2.1 2.1M7.7 16.3l-2.1 2.1m12.8 0-2.1-2.1M7.7 7.7 5.6 5.6"/><circle cx="12" cy="12" r="4"/>',
 refresh:'<path d="M20 11a8 8 0 0 0-14.8-3M4 3v5h5M4 13a8 8 0 0 0 14.8 3M20 21v-5h-5"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 external:'<path d="M13 5h6v6M19 5 10 14M19 13v6H5V5h6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 warning:'<path d="m12 3 10 18H2z"/><path d="M12 9v5m0 3v.3"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c4 5 4 13 0 18M12 3c-4 5-4 13 0 18"/>',
 git:'<circle cx="6" cy="6" r="2"/><circle cx="18" cy="8" r="2"/><circle cx="6" cy="18" r="2"/><path d="M6 8v8M8 6h4a6 6 0 0 1 6 6V10"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',
 upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',
 more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
 edit:'<path d="M5 17l-.7 3.2L8 19l11-11-3-3L5 16.5zM14 7l3 3"/>',
 trash:'<path d="M4 7h16M10 3h4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',
 close:'<path d="M5 5l14 14M19 5 5 19"/>',
 server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.1M7 17.5h.1M12 6.5h6M12 17.5h6"/>',
 code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M13 4l-2 16"/>',
 folder:'<path d="M3 5h7l2 3h9v12H3z"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 trend:'<path d="M3 19h18M4 15l6-5 4 3 6-8M15 5h5v5"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9v.2"/>',
 document:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h8"/>',
 list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1"/>',
 shield:'<path d="M12 2 20 6v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/><path d="m8 12 3 3 5-6"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'
};
function ico(name,cls=''){return `<svg class="${cls}" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function href(url){const s=String(url||'');return /^https:\/\/[\w.\-]+(?:[:\/\?#]|$)/i.test(s)?esc(s):'#';}
function fmt(num){return Number(num||0).toLocaleString('en-US');}
function shortDate(t){if(!t)return 'Not checked';const d=new Date(t);return Number.isNaN(d.getTime())?'Unknown':new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d);}
function ago(t){if(!t)return 'Unknown';const diff=Date.now()-new Date(t).getTime();if(!Number.isFinite(diff))return 'Unknown';if(diff<0)return 'just now';if(diff<60000)return 'just now';if(diff<3600000)return `${Math.floor(diff/60000)}m ago`;if(diff<86400000)return `${Math.floor(diff/3600000)}h ago`;if(diff<86400000*30)return `${Math.floor(diff/86400000)}d ago`;return shortDate(t);}
function project(id){return (model?.projects||[]).find(p=>p.id===id);}
function gh(p){return p?.github?.data||{};}
function goals(projectId){return (model?.goals||[]).filter(g=>!projectId||g.project===projectId);}
function activeGoals(projectId){return goals(projectId).filter(g=>g.state!=='done');}
function currentHash(){const h=location.hash.replace(/^#/,'');return ['overview','latitude','longitude','sundial','activity','analytics','settings'].includes(h)?h:'overview';}
function niceStage(p){return p.stage||'In development';}
function releaseTag(p){return gh(p).release?.tag_name||'—';}
function ghLink(p){return `https://github.com/${p.repository}`;}
function pill(label,kind='dim'){return `<span class="status-pill ${kind}"><span class="status-dot"></span>${esc(label)}</span>`;}
function cardSym(p){return `<div class="project-symbol ${p.id==='longitude'?'lon':p.id==='sundial'?'sun':''}">${p.id==='latitude'?'L':p.id==='longitude'?'Lo':'S'}</div>`;}
function githubState(p){const g=gh(p),r=g.ci;if(!r)return {name:'No build data',tone:'dim'};if(r.status!=='completed')return {name:'Build in progress',tone:'warn'};if(r.conclusion==='success')return {name:'Build passed',tone:'good'};if(r.conclusion==='failure')return {name:'Build failed',tone:'bad'};return {name:`Build ${r.conclusion||'unknown'}`,tone:'dim'};}
function sitesState(p){const ss=p.sites.map(s=>sampleTone(s.status));if(ss.includes('bad'))return {name:'Endpoint failed',tone:'bad'};if(ss.includes('warn'))return {name:'Verification needed',tone:'warn'};return {name:'Endpoints responding',tone:'good'};}
function overviewStatus(p){const ci=githubState(p),site=sitesState(p);if(p.id==='sundial'&&gh(p).uptime_workflow?.conclusion==='failure')return {name:'Investigate monitor',tone:'warn'};if(site.tone==='bad')return site;if(ci.tone==='bad')return ci;if(site.tone==='warn')return site;return {name:'Checks responding',tone:'good'};}
function alerts(){const out=[];for(const p of model.projects){const g=gh(p),up=g.uptime_workflow;
 if(p.id==='sundial'&&up?.conclusion==='failure'){out.push({project:p.id,title:'Sundial uptime workflow is failing',detail:'The last reported GitHub health-check run failed. Inspect the job and compare it with a live sync endpoint check.',url:up.html_url,level:'warn'});}
 const down=p.sites.filter(x=>x.status&&!x.status.success);for(const s of down){const recent=new Date(s.status.checked_at).getTime()>Date.now()-1000*60*60*4;out.push({project:p.id,title:`${p.name}: ${s.label} check failed`,detail:`${recent?'Latest':'Last stored'} check: ${s.status.error||'Unsuccessful response'}. This is a probe result, not proof of prolonged downtime.`,url:s.url,level:'warn'});}
 for(const s of p.sites){if(s.status?.success&&s.status.tls_days!==null&&s.status.tls_days!==undefined&&s.status.tls_days<15)out.push({project:p.id,title:`${p.name}: ${s.label} certificate nearing expiry`,detail:`Last reported ${s.status.tls_days} days until TLS certificate expiration.`,url:s.url,level:'warn'});}
 if(g.ci?.conclusion==='failure')out.push({project:p.id,title:`${p.name} build needs attention`,detail:`Latest recorded development workflow “${g.ci.name}” failed.`,url:g.ci.html_url,level:'warn'});
 if(p.github?.error && !p.github.error.includes('Initial verified')){out.push({project:p.id,title:`${p.name}: GitHub refresh unavailable`,detail: p.github.error.length>160?p.github.error.slice(0,160)+'…':p.github.error,level:'info'});}
 }if(model.updates?.state==='available')out.unshift({project:'meridian',title:`Meridian v${model.updates.latest} is available`,detail:'An updated installer is available. Your local data is kept when you upgrade.',url:model.updates.release_url,level:'info'});return out;}
function recommendations(pid){const all=activeGoals(pid);const score=g=>({critical:100,high:70,medium:40,low:10}[g.priority]||30)+(g.state==='doing'?25:0)+(g.category==='Operations'?9:0);return [...all].sort((a,b)=>score(b)-score(a)||a.id-b.id).slice(0,pid?7:6);}
function topNav(){const items=[['overview','Overview','overview'],['latitude','Latitude','L'],['longitude','Longitude','Lo'],['sundial','Sundial','S'],['activity','Activity','activity'],['analytics','Analytics','chart'],['settings','Settings','settings']];const nodes=[];
 for(let i=0;i<items.length;i++){if(i===1||i===4)nodes.push(`<div class="nav-separator" aria-hidden="true"></div>`);const [id,label,kind]=items[i];const sym=['L','Lo','S'].includes(kind)?`<span class="nav-project-dot">${kind}</span>`:ico(kind,'nav-icon');nodes.push(`<a href="#${id}" class="nav-item ${current===id?'active':''}" title="${label}">${sym}<span class="nav-text">${label}</span></a>`);}$('#main-nav').innerHTML=nodes.join('');$('#crumb-current').textContent={overview:'Overview',latitude:'Latitude',longitude:'Longitude',sundial:'Sundial',activity:'Activity',analytics:'Analytics',settings:'Settings'}[current]||'Overview';}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function stat(label,value,sub,color=''){return `<div class="stat-tile"><div class="stat-label">${esc(label)}</div><div class="stat-value ${color}">${esc(value)}</div><div class="stat-sub">${esc(sub)}</div></div>`;}
function section(title,subtitle,extra=''){return `<div class="section-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${extra}</div>`;}
function projectCard(p){const s=overviewStatus(p);return `<article tabindex="0" role="link" data-go="${p.id}" class="panel project-card" aria-label="Open ${p.name} workspace"><div class="project-top">${cardSym(p)}${pill(s.name,s.tone)}</div><div><h3>${esc(p.name)}</h3><div class="kind">${esc(p.kind)}</div></div><div class="project-version"><div><div class="project-release">${esc(releaseTag(p))}</div><div class="project-meta">Latest published release</div></div>${ico('arrow','small-arrow')}</div><div class="card-bottom"><span>${esc(niceStage(p))}</span><span>${fmt(activeGoals(p.id).length)} open goals</span></div></article>`;}
function alertMarkup(items,max=3){if(!items.length)return `<div class="subtle-card"><div class="tag-head" style="color:#b5d693">${ico('shield')}<strong>Nothing urgent from the latest available checks</strong></div><div class="caption-line" style="margin-top:6px">Status reflects available monitoring results, not a guarantee of uptime.</div></div>`;return `<div class="alert-stack">${items.slice(0,max).map(a=>`<div class="notice"><span class="alert-icon">${ico(a.level==='info'?'info':'warning')}</span><div style="flex:1"><strong>${esc(a.title)}</strong><div style="margin-top:4px">${esc(a.detail)}</div>${a.url?`<a class="inline-link" href="${href(a.url)}" target="_blank" rel="noreferrer" style="display:inline-block;margin-top:5px">Inspect ${ico('external')}</a>`:''}</div></div>`).join('')}${items.length>max?`<div class="alerts-more">${items.length-max} more status notices in project pages</div>`:''}</div>`;}
function goalRow(g,actions=true){return `<div class="work-row"><button class="work-ring ${g.state==='done'?'done':''}" aria-label="${g.state==='done'?'Mark not done':'Complete goal'}" title="${g.state==='done'?'Reopen':'Mark complete'}" data-goal-state="${g.id}" data-state="${g.state==='done'?'todo':'done'}">${g.state==='done'?ico('check','tickbox'):ico('check','tickbox')}</button><div class="work-main"><span class="work-title ${g.state==='done'?'done':''}">${esc(g.title)}</span><div class="work-caption"><span>${esc(labels[g.project])}</span><span>${esc(g.category)}</span><span style="color:${g.priority==='critical'?'#ee9c84':g.priority==='high'?'#e7c187':'#879788'}">${esc(g.priority.toUpperCase())}</span>${g.state==='doing'?'<span style="color:#d1ff4a">IN PROGRESS</span>':''}</div></div>${actions?`<div class="work-actions"><button class="text-action" title="Copy development prompt" data-prompt-project="${g.project}" data-prompt-goal="${g.id}">${ico('code')}</button>${g.state==='todo'?`<button class="text-action" data-goal-state="${g.id}" data-state="doing">Start</button>`:''}<button class="text-action" title="Edit task" data-edit-goal="${g.id}">${ico('edit')}</button></div>`:''}</div>`;}
function recentActivities(pid,limit=6){const rows=model.events.filter(e=>!pid||e.project===pid).slice(0,limit);if(!rows.length)return empty('Activity will appear after GitHub has been refreshed.','activity');return rows.map(e=>`<div class="activity-row"><div class="activity-icon">${ico(e.kind==='release'?'download':'git')}</div><div class="activity-text"><a href="${href(e.link)}" target="_blank" rel="noreferrer"><strong title="${esc(e.title)}">${esc(e.title)}</strong></a><small>${esc(labels[e.project])} · ${esc(e.kind)} · ${ago(e.happened_at)}</small></div></div>`).join('');}
function empty(msg,which='info'){return `<div class="empty">${ico(which)}${esc(msg)}</div>`;}
function siteItem(s){const status=s.status,tone=sampleTone(status);return `<div class="site-line"><div class="site-indicator ${tone}"></div><div class="site-details"><strong>${esc(s.label)}</strong><span class="small">${esc(s.url)}</span></div><div class="site-meta">${status?`${checkName(tone)} · ${ago(status.checked_at)}`:'Awaiting check'}</div><a href="${href(s.url)}" target="_blank" rel="noreferrer" class="site-arrow" title="Open address">${ico('external')}</a></div>`;}
function sampleTone(status, maxAgeMinutes=25){
 if(!status || !status.checked_at)return 'warn';
 const elapsed=Date.now()-Date.parse(status.checked_at);
 if(!Number.isFinite(elapsed)||elapsed>maxAgeMinutes*60000)return 'warn';
 return status.success?'good':'bad';
}
function checkName(tone){return tone==='good'?'Online':'bad'===tone?'Failed':'Unverified';}
function strongLight(label,tone,detail=''){
 return `<span class="health-light ${tone}" title="${esc(detail)}"><span class="light-orb"></span><span>${esc(label)}</span></span>`;
}
function siteLight(site){
 const status=site.status,tone=sampleTone(status);
 const detail=!status?'No samples yet':tone==='warn'?'The last check is too old to confirm current availability':(status.success?`HTTP ${status.status}, checked ${ago(status.checked_at)}`:(status.error||`HTTP ${status.status||'unknown'}`));
 return strongLight(`${site.label}: ${checkName(tone)}`,tone,detail);
}
function ciLight(p){
 const g=gh(p),ci=g.ci,t=Date.parse(ci?.updated_at||ci?.created_at||p.github?.checked_at||'');
 if(!ci)return strongLight('Build: Unknown','warn','No CI data collected');
 const stale=!Number.isFinite(t)||Date.now()-t>14*86400000;
 const tone=stale?'warn':ci.status==='completed'&&ci.conclusion==='success'?'good':ci.status==='completed'&&ci.conclusion==='failure'?'bad':'warn';
 return strongLight(`Build: ${tone==='good'?'Passed':tone==='bad'?'Failed':'Unverified'}`,tone,`Latest GitHub workflow: ${ci.name||'Unknown'}; ${ci.conclusion||ci.status||'unknown'}`);
}
function siteHistoryChart(p){
 const hours=Array.from({length:48},(_,i)=>new Date(Math.floor(Date.now()/3600000)*3600000-(47-i)*3600000).toISOString().slice(0,13));
 const rows=(model.site_48h||[]).filter(x=>x.project===p.id);
 const sites=p.sites.filter(x=>x.type==='health'||x.type==='landing'||x.type==='app');
 const lines=sites.map(site=>{
  const idx=new Map(rows.filter(r=>r.url===site.url).map(r=>[r.hour,r]));
  let success=0,total=0;
  const cells=hours.map(hr=>{
   const sample=idx.get(hr),tone=!sample?'unknown':Number(sample.passed)===Number(sample.checks)?'good':'bad';
   if(sample){success+=Number(sample.passed);total+=Number(sample.checks);}
   return `<span class="history-cell ${tone}" title="${esc(hr.replace('T',' ')+' UTC')} · ${sample?`${sample.passed}/${sample.checks} successful probes`:'No probe recorded'}"></span>`;
  }).join('');
  return `<div class="history-line"><div class="history-label"><span>${esc(site.label)}</span><small>${total?`${success}/${total} checks passed`:'No checks yet'}</small></div><div class="history-cells">${cells}</div></div>`;
 }).join('');
 return `<div class="panel health-history"><div class="panel-header"><div><h3>Last 48 hours</h3><p class="subtext">Hourly probe history · while Meridian is running</p></div>${strongLight('Live checks',p.sites.some(x=>sampleTone(x.status)==='bad')?'bad':p.sites.every(x=>sampleTone(x.status)==='good')?'good':'warn')}</div>${lines}<div class="history-foot"><span>48 hours ago</span><span>Now</span></div><div class="health-legend"><span><i class="legend-box good"></i> Success</span><span><i class="legend-box bad"></i> Failed</span><span><i class="legend-box unknown"></i> No sample</span></div><p class="caption-line">Missing hours remain unknown, not green. This history is not a 24/7 SLA report.</p></div>`;
}
function projectVitals(p){
 const hasDl=model.download_assets.some(a=>a.project===p.id);
 const entries=(model.web_analytics||[]).filter(a=>a.project===p.id&&a.date>=new Date(Date.now()-6*86400000).toISOString().slice(0,10));
 const visits=entries.length?fmt(entries.reduce((n,x)=>n+Number(x.visitors||0),0)):'—';
 return `<div class="panel project-vitals"><div class="panel-header"><div><h3>Live status & audience</h3><p class="subtext">One glance at what can actually be checked</p></div><button class="soft-button" data-prompt-project="${p.id}">${ico('code')} Copy troubleshooting prompt</button></div><div class="vitals-lights">${p.sites.map(siteLight).join('')}${ciLight(p)}${p.id==='sundial'?strongLight('GitHub uptime job',gh(p).uptime_workflow?.conclusion==='success'?'good':gh(p).uptime_workflow?.conclusion==='failure'?'bad':'warn','Scheduled GitHub monitor; separate from a direct sync probe'):''}</div><div class="vitals-metrics"><div><strong>${hasDl?fmt(p.latest_downloads):'—'}</strong><span>Latest-release downloads*</span></div><div><strong>${visits}</strong><span>Visitors, imported 7 days</span></div><div><strong>${fmt(activeGoals(p.id).filter(g=>g.state==='doing').length)}</strong><span>In progress</span></div></div><p class="caption-line">*Cumulative GitHub download requests, not active users. Visitor counts appear only when analytics are imported. These lights monitor endpoints and builds, not whether a local desktop app is running.</p></div>`;
}
function makeRepairPrompt(pid,goalId=null,siteIndex=null){
 const p=project(pid),g=gh(p),task=goalId?model.goals.find(x=>x.id===goalId&&x.project===pid):recommendations(pid)[0];
 const site=siteIndex===null?null:p.sites[Number(siteIndex)];
 const checks=p.sites.map(s=>`${s.label}: ${sampleTone(s.status)==='good'?'responding':sampleTone(s.status)==='bad'?'failed':'unverified'}${s.status?.status?` (HTTP ${s.status.status})`:''}${s.status?.error?` — ${s.status.error}`:''}`).join('; ');
 const focus=site?`Investigate ${site.label} (${site.url}). Last result: ${JSON.stringify(site.status||'not checked')}`:task?`${task.title}. ${task.description||''}`:`Review ${p.name} for the highest-priority unresolved issue.`;
 return `You are helping maintain ${p.name}, repository https://github.com/${p.repository}.\nCurrent published version: ${releaseTag(p)}.\nTask: ${focus}\nMonitoring evidence (may be stale): ${checks}.\nLatest CI: ${g.ci?.name||'unknown'} — ${g.ci?.conclusion||'unverified'}.\n\nPlease inspect the repository and reproduce the issue before editing. Diagnose the root cause, make the smallest safe fixes, add or improve tests, and run the relevant checks. Preserve local-first/privacy behavior and existing functionality. Do not assume a green CI build proves real-device behavior. Summarize exactly what changed, what was tested, remaining risks, and the next actionable step. Update PROJECT_STATUS.md or docs/ROADMAP.md with verified progress. Do not mark manual hardware/uptime testing complete unless verified.`;
}
async function copyRepairPrompt(pid,goalId=null,siteIndex=null){
 const msg=makeRepairPrompt(pid,goalId,siteIndex);
 try{await navigator.clipboard.writeText(msg);toast('Prompt copied — paste into ChatGPT or Claude.');}
 catch(e){showPromptModal(msg);}
}
function showPromptModal(msg){const d=document.createElement('div');d.className='modal-backdrop';d.id='prompt-backdrop';d.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Copy this project prompt</h2><p>Paste it into your ChatGPT or Claude coding session.</p></div><button class="icon-btn" data-close-prompt aria-label="Close">${ico('close')}</button></div><textarea class="prompt-text" readonly></textarea><div class="modal-footer"><button class="primary-button" data-select-prompt>Select all text</button></div></div>`;document.body.append(d);d.querySelector('textarea').value=msg;d.querySelector('textarea').focus();d.querySelector('textarea').select();}

function overview(){const ps=model.projects,a=alerts(),tasks=recommendations(),n=goals(),done=n.filter(g=>g.state==='done').length;
 const activeSites=ps.flatMap(p=>p.sites).filter(s=>s.status),checksGood=activeSites.filter(s=>s.status.success).length;
 const rels=ps.reduce((s,p)=>s+(gh(p).release?1:0),0),trackedDownloads=ps.reduce((s,p)=>s+(p.latest_downloads||0),0),haveDownloadData=model.download_assets.length>0;
 return heading('Your development, organized','Your workspace, at a glance.','Three products. One place to see what changed, what needs attention, and what comes next.',`<button class="soft-button" data-modal="goal">${ico('plus')} Add a goal</button><button class="primary-button" data-modal="note">${ico('note')} Quick note</button>`)
 + `<div class="stat-grid">${stat('Active projects',ps.length,'Latitude · Longitude · Sundial')}${stat('Goals completed',`${done} / ${n.length}`,'Manually verified work', 'stat-good')}${stat('Latest release downloads',haveDownloadData?fmt(trackedDownloads):'—',haveDownloadData?'Across the 3 latest releases':'Waiting for GitHub sync')}${stat('Web checks · verified',activeSites.length?`${activeSites.filter(s=>sampleTone(s.status)==='good').length} / ${ps.flatMap(p=>p.sites).length}`:'—','Only recent successful HTTP probes',activeSites.some(s=>sampleTone(s.status)!=='good')?'stat-warning':'')}</div>`
 + `<div class="portfolio-lights">${ps.map(p=>`<div class="portfolio-light-row"><strong>${esc(p.name)}</strong><div>${p.sites.map(siteLight).join('')}</div></div>`).join('')}</div>`
 + section('Your projects','Latest releases, development status and current priorities')+`<div class="grid3">${ps.map(projectCard).join('')}</div>`
 + section('Needs your attention','Verified workflow results and endpoint checks')+alertMarkup(a)
 + `<div class="two-column"><div>${section('What to work on next','Suggested order from your goals and operational priorities',`<a class="muted-link" href="#latitude">Manage goals ${ico('arrow')}</a>`)}<div class="panel">${tasks.slice(0,4).map(g=>goalRow(g)).join('')||empty('Add a goal to start prioritizing your work.','target')}<div class="small-annotation">These are recommendations, not automatic claims that any work is finished.</div></div></div><div>${section('Recent development','Latest recorded releases and commits',`<a class="muted-link" href="#activity">View history ${ico('arrow')}</a>`)}<div class="panel">${recentActivities(null,7)}</div></div></div>`
 + section('Sites and services','Real checks from this machine while Meridian is open')+`<div class="grid3">${ps.map(p=>`<div class="panel"><div class="panel-header"><h3>${esc(p.name)}</h3>${pill(sitesState(p).name,sitesState(p).tone)}</div><div class="sites-list">${p.sites.map(siteItem).join('')}</div></div>`).join('')}</div>`;
}
function quickLinks(p){const arr=[`<a class="soft-button" href="${href(ghLink(p))}" target="_blank" rel="noreferrer">${ico('code')} Repository ${ico('external')}</a>`];if(gh(p).release?.html_url)arr.push(`<a class="soft-button" href="${href(gh(p).release.html_url)}" target="_blank" rel="noreferrer">${ico('download')} Latest release</a>`);return arr.join('');}
function projectView(p){const g=gh(p),r=g.release||{},completed=goals(p.id).filter(x=>x.state==='done').length,all=goals(p.id),ci=githubState(p),a=alerts().filter(x=>x.project===p.id);
 const q=quickLinks(p);
 let html=`<div class="page-heading"><div><div class="eyebrow">PROJECT / ${esc(p.id.toUpperCase())}</div><div class="hero-project">${cardSym(p)}<div><h1>${esc(p.name)}</h1><div class="tagline">${esc(p.description)}</div></div></div><div class="secondary-chips">${pill(niceStage(p),'dim')}${pill(ci.name,ci.tone)}</div></div><div class="page-actions">${q}</div></div>`;
 html+=`<div class="stat-grid">${stat('Latest release',r.tag_name||'—',r.published_at?`Published ${shortDate(r.published_at)}`:'No release yet')}${stat('Next actions',activeGoals(p.id).length,'Open project goals')}${stat('Completed',completed,`${all.length} total recorded goals`,'stat-good')}${stat('Release downloads',model.download_assets.some(d=>d.project===p.id)?fmt(p.latest_downloads):'—','Latest published version')}</div>`;
 html+=projectVitals(p)+siteHistoryChart(p);
 if(a.length)html+=section('Attention','Current project alerts')+alertMarkup(a,2);
 const tabs=[['plan','Plan & goals'],['notes','Journal'],['history','Development history'],['decisions','Decisions'],['releases','Releases & sites']];
 html+=`<div class="tabs" role="tablist">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${projectTab===id}" class="tab ${projectTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`;
 if(projectTab==='plan')html+=planTab(p);
 else if(projectTab==='notes')html+=notesTab(p);
 else if(projectTab==='history')html+=historyTab(p);
 else if(projectTab==='decisions')html+=decisionsTab(p);
 else html+=releasesTab(p);
 return html;
}
function planTab(p){const g=goals(p.id),pending=g.filter(x=>x.state!=='done'),finished=g.filter(x=>x.state==='done');
 const roadmap=gh(p).roadmap, repoIssues=gh(p).issues||[];
 const docsPanel=roadmap?`<div class="panel" style="margin-top:16px"><div class="panel-header"><h3>From the repository roadmap</h3><a class="muted-link" href="${href(roadmap.url)}" target="_blank" rel="noreferrer">Source ${ico('external')}</a></div>${roadmap.open_items?.length?roadmap.open_items.slice(0,6).map(item=>`<div class="work-row"><div class="work-main"><div class="work-title">${esc(item)}</div></div><button class="text-action" data-promote="${esc(item)}" data-promote-project="${p.id}" title="Copy to tracked goals">${ico('plus')}</button></div>`).join(''):'<p class="caption-line">Roadmap found. No unchecked Markdown tasks were detected.</p>'}<div class="small-annotation">Items are read from ${esc(roadmap.file)}, not marked complete automatically. Use + to track an item locally.</div></div>`:`<div class="panel" style="margin-top:16px"><div class="panel-header"><h3>Living project status</h3></div><p class="caption-line">Add a <code>PROJECT_STATUS.md</code> file at the repository root to feed human-authored milestones into Meridian on each refresh.</p></div>`;
 const issuesPanel=repoIssues.length?`<div class="panel" style="margin-top:16px"><div class="panel-header"><h3>Open GitHub issues & PRs</h3></div>${repoIssues.slice(0,6).map(i=>`<div class="work-row"><div class="work-main"><a class="work-title inline-link" target="_blank" rel="noreferrer" href="${href(i.url)}">${esc(i.title)}</a><div class="work-caption">${i.pull_request?'Pull request':'Issue'} #${i.number}</div></div></div>`).join('')}</div>`:'';
 return `<div class="two-column"><div><div class="panel-header" style="margin-bottom:14px"><div><h3>Current roadmap</h3><p class="subtext" style="margin-top:5px">${pending.length} active goals · ${finished.length} completed</p></div><button class="primary-button" data-modal="goal" data-project="${p.id}">${ico('plus')} Goal</button></div><div class="panel">${pending.length?pending.slice(0,goalExpanded[p.id]?pending.length:4).map(goalRow).join(''):empty('No open goals here. Add your next milestone.','target')}${pending.length>4?`<button class="soft-button goal-toggle" data-toggle-goals="${p.id}">${goalExpanded[p.id]?'Show top four':'Show all '+pending.length+' open goals'}</button>`:''}${finished.length?`<details class="completed-list"><summary>${finished.length} completed goals</summary>${finished.map(goalRow).join('')}</details>`:''}</div></div><div><div class="panel"><div class="panel-header"><h3>Progress at a glance</h3>${pill(niceStage(p),'dim')}</div><div class="status-brief"><strong>Focus:</strong> ${esc(recommendations(p.id)[0]?.title||'No open goals')}</div><div style="margin-top:17px"><span class="small-label">Tracked goal completion</span><div class="mini-progress"><span style="width:${g.length?Math.round(100*finished.length/g.length):0}%"></span></div><div class="caption-line" style="margin-top:7px">${finished.length} of ${g.length} goals marked done. Not a measure of total product completeness.</div></div><hr class="divider"/><div class="small-label">WHY THIS WORK MATTERS</div><p class="roadmap-hint">${esc(p.id==='latitude'?'Focus on actual device verification and editor usability. A green build is not the same as a tested recording.':p.id==='longitude'?'A complete creator workflow matters more than feature count. Verify browser and packaged versions independently.':'Sync uptime and recoverable backups are operational requirements. Check these before adding new platforms.')}</p></div><div class="panel" style="margin-top:16px"><div class="panel-header"><h3>Quick access</h3></div><div class="project-quicklinks">${quickLinks(p)}</div><hr class="divider"/><div class="caption-line">Source documentation can inform goals, but only you should mark a real-world test complete.</div></div>${docsPanel}${issuesPanel}</div></div>`;
}
function notesTab(p){const notes=model.notes.filter(x=>x.project===p.id);return `<div class="panel-header"><div><h3>Development journal</h3><p class="subtext" style="margin-top:5px">Keep context from ChatGPT, Claude, and real testing together.</p></div><button class="primary-button" data-modal="note" data-project="${p.id}">${ico('plus')} Note</button></div>${notes.length?`<div class="notes-grid">${notes.map(x=>`<article class="panel note-card"><div class="panel-header"><span class="note-category">MANUAL NOTE</span><button class="text-action" data-delete="notes" data-id="${x.id}" title="Delete note">${ico('trash')}</button></div><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><div class="item-date">${shortDate(x.created_at)}</div></article>`).join('')}</div>`:empty('Your journal is empty. Save a short note after a coding session to preserve the important context.','note')}`;}
function historyTab(p){const events=model.events.filter(x=>x.project===p.id);return `<div class="two-column"><div><div class="panel-header"><h3>GitHub development timeline</h3>${pill(`${events.length} recorded events`,'dim')}</div><div class="panel">${events.length?recentActivities(p.id,100):empty('Run the first GitHub refresh to collect commits and release events.','git')}</div></div><div><div class="panel"><div class="panel-header"><h3>Source status</h3></div><div class="keyvalue"><label>Repository</label><span class="value"><a href="${href(ghLink(p))}" target="_blank" rel="noreferrer">${esc(p.repository)} ${ico('external')}</a></span></div><div class="keyvalue"><label>Last push</label><span class="value">${ago(gh(p).repo?.pushed_at)}</span></div><div class="keyvalue"><label>Build</label><span class="value">${esc(githubState(p).name)}</span></div><div class="keyvalue"><label>GitHub checked</label><span class="value">${ago(p.github.checked_at)}</span></div><div class="keyvalue"><label>Open issues / PRs</label><span class="value">${(gh(p).issues||[]).length}</span></div><hr class="divider"/><p class="caption-line">Commit messages and published releases are factual history. They do not confirm that features work in production.</p></div></div></div>`;}
function decisionsTab(p){const arr=model.decisions.filter(x=>x.project===p.id);return `<div class="panel-header"><div><h3>Decision log</h3><p class="subtext" style="margin-top:5px">Record important choices so future development sessions keep the same direction.</p></div><button class="primary-button" data-modal="decision" data-project="${p.id}">${ico('plus')} Decision</button></div>${arr.length?`<div class="notes-grid">${arr.map(x=>`<article class="panel note-card"><div class="panel-header"><span class="note-category">DECISION</span><button class="text-action" data-delete="decisions" data-id="${x.id}" title="Delete decision">${ico('trash')}</button></div><h3>${esc(x.title)}</h3><p>${esc(x.reason)}</p><div class="item-date">${shortDate(x.created_at)}</div></article>`).join('')}</div>`:empty('Decisions recorded here help maintain continuity between coding assistants.','document')}`;}
function releasesTab(p){const g=gh(p),rs=g.releases||[g.release].filter(Boolean);const after=new Date(Date.now()-7*86400000).toISOString().slice(0,10);const healthRows=p.sites.map(site=>{const rows=model.site_history.filter(r=>r.project===p.id&&r.label===site.label&&r.day>=after);const checks=rows.reduce((a,r)=>a+Number(r.checks),0),passed=rows.reduce((a,r)=>a+Number(r.passed),0);return `<div class="keyvalue"><label>${esc(site.label)}</label><span class="value">${checks?`${Math.round(100*passed/checks)}% · ${fmt(passed)}/${fmt(checks)} probes`:'No samples yet'}</span></div>`;}).join('');return `<div class="two-column"><div><div class="panel"><div class="panel-header"><h3>Release history</h3></div>${rs.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Version</th><th>Published</th><th>Downloads*</th></tr></thead><tbody>${rs.map(r=>`<tr><td><a class="inline-link" href="${href(r.html_url)}" target="_blank" rel="noreferrer">${esc(r.tag_name)} ${r.prerelease?'<span class="mini-tag">Beta</span>':''}</a></td><td>${shortDate(r.published_at)}</td><td>${(r.assets||[]).length?fmt(r.assets.filter(a=>/\.(exe|dmg|zip|flatpak|deb|rpm|AppImage)$/i.test(a.name||'')).reduce((s,a)=>s+Number(a.download_count||0),0)):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No releases loaded.','download')}<p class="caption-line" style="margin-top:14px">*GitHub release-asset download requests, not installations or unique users.</p></div></div><div><div class="panel"><div class="panel-header"><h3>Web properties</h3></div><div class="sites-list">${p.sites.map(siteItem).join('')}</div><hr class="divider"/><div class="small-label">RECENT PROBE RESULTS · 7 DAYS</div>${healthRows}<p class="caption-line" style="margin-top:9px">Percentage of successful Meridian checks while running; not guaranteed 24/7 uptime.</p>${p.id==='longitude'?`<hr class="divider"/><div class="caption-line">longitude.pictures is planned, not registered in Meridian as a live site.</div>`:''}${p.id==='sundial'?`<hr class="divider"/><div class="caption-line">Backup verification: not connected. Add a protected server-side last-successful-backup report before treating backups as monitored.</div>`:''}</div></div></div>`;}
function activityPage(){const arr=model.events;
 return heading('Across all projects','Development timeline','A factual log of commits and releases observed by Meridian.',`<button class="soft-button" data-modal="note">${ico('plus')} Add context note</button>`)
 + `<div class="panel"><div class="panel-header"><h3>Recorded events</h3>${pill(`${arr.length} events`,'dim')}</div>${arr.length?arr.map(e=>`<div class="activity-row"><div class="activity-icon">${ico(e.kind==='release'?'download':'git')}</div><div class="activity-text"><a href="${href(e.link)}" target="_blank" rel="noreferrer"><strong>${esc(e.title)}</strong></a><small>${esc(labels[e.project])} · ${esc(e.kind)} · ${shortDate(e.happened_at)}</small>${e.detail?`<div class="caption-line" style="margin-top:7px">${esc(e.detail)}</div>`:''}</div><span class="mini-tag">${esc(e.project)}</span></div>`).join(''):empty('GitHub history will populate after the first successful refresh.','git')}</div>`;
}
function lineChart(values,axisLabels){if(values.length<2)return empty('Collect at least two dated measurements to display a trend.','chart');const w=660,h=205,padX=36,padTop=19,padBottom=33;const min=0,max=Math.max(1,...values)*1.12, plotW=w-padX-14,plotH=h-padTop-padBottom;const px=i=>padX+i*plotW/(values.length-1),py=v=>padTop+(max-v)/max*plotH;const coords=values.map((v,i)=>`${px(i).toFixed(1)},${py(v).toFixed(1)}`);const poly=coords.join(' ');const fill=`${px(0)},${h-padBottom} ${poly} ${px(values.length-1)},${h-padBottom}`;return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Traffic trend graph" class="graph"><defs><linearGradient id="fade-lime" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#d1ff4a" stop-opacity=".26"/><stop offset="1" stop-color="#d1ff4a" stop-opacity="0"/></linearGradient></defs>${[0,.33,.66,1].map(f=>`<line class="gridline" x1="${padX}" y1="${py(max*f)}" x2="${w-14}" y2="${py(max*f)}"/><text class="axis-text" x="2" y="${py(max*f)+4}">${Math.round(max*f).toLocaleString('en-US')}</text>`).join('')}<polygon class="area" points="${fill}"/><polyline class="line" points="${poly}"/><text class="axis-text" x="${padX}" y="${h-7}">${esc(axisLabels[0])}</text><text class="axis-text" x="${w-14}" text-anchor="end" y="${h-7}">${esc(axisLabels.at(-1))}</text></svg>`;}
function barChart(entries,label){
 const present=entries.filter(x=>x.value!==null);if(!present.length)return empty('This chart will appear when comparable measurements are available.','chart');
 const w=640,h=190,left=42,bottom=28,top=18,plot=w-left-8,max=Math.max(1,...present.map(x=>x.value));
 const step=plot/entries.length;
 return `<svg class="metric-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${[0,.5,1].map(f=>{const y=top+(h-bottom-top)*(1-f);return `<line x1="${left}" x2="${w}" y1="${y}" y2="${y}" stroke="#2a3431"/><text x="0" y="${y+4}" fill="#8d9a95" font-size="10">${fmt(Math.round(max*f))}</text>`;}).join('')}${entries.map((x,i)=>{const height=x.value===null?2:Math.max(2,x.value/max*(h-top-bottom)),px=left+i*step+2;return `<rect x="${px}" y="${h-bottom-height}" width="${Math.max(2,step-5)}" height="${height}" rx="3" fill="${x.value===null?'#35413b':'#c3f66b'}"><title>${esc(x.date)}: ${x.value===null?'not measured':fmt(x.value)}</title></rect>`;}).join('')}<text x="${left}" y="${h-5}" fill="#8d9a95" font-size="10">${esc(entries[0].date.slice(5))}</text><text x="${w}" y="${h-5}" fill="#8d9a95" text-anchor="end" font-size="10">${esc(entries.at(-1).date.slice(5))}</text></svg>`;
}
function analyticsPage(){
 const ps=model.projects.filter(p=>analyticsProject==='all'||p.id===analyticsProject);
 const chosen=x=>analyticsProject==='all'||x.project===analyticsProject;
 const growth=MeridianMetrics.downloadGrowth(model.download_history,analyticsDays,analyticsProject);
 const start=growth.dates[0].date,end=growth.dates.at(-1).date;
 const traffic=model.web_analytics.filter(x=>chosen(x)&&x.date>=start&&x.date<=end);
 const trafficMap=new Map();for(const x of traffic)trafficMap.set(x.date,(trafficMap.get(x.date)||0)+x.pageviews);
 const probes=(model.site_metrics||[]).filter(chosen),checks=probes.reduce((s,r)=>s+r.checks,0),passed=probes.reduce((s,r)=>s+r.passed,0);
 const done=model.goals.filter(g=>chosen(g)&&g.state==='done'&&g.completed_at?.slice(0,10)>=start&&g.completed_at.slice(0,10)<=end).length;
 const filters=`<div class="analytics-controls"><label class="sr-only" for="analytics-project">Project</label><select id="analytics-project"><option value="all">All projects</option>${ps.length===model.projects.length?projectOptions(null):model.projects.map(p=>`<option value="${p.id}" ${analyticsProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div class="segmented">${[7,30].map(n=>`<button data-analytics-days="${n}" aria-pressed="${n===analyticsDays}">${n} days</button>`).join('')}</div><button class="soft-button" data-modal="analytics">${ico('upload')} Import traffic</button></div>`;
 let html=heading('MEASURE / UNDERSTAND','Project insights','Downloads, reliability and progress from your recorded data.',filters);
 html+=`<div class="stat-grid">${stat('Observed download growth',growth.total===null?'—':'+'+fmt(growth.total),`${analyticsDays} days · comparable asset snapshots`,'stat-good')}${stat('Imported visitors',traffic.length?fmt(traffic.reduce((s,r)=>s+r.visitors,0)):'—',`${analyticsDays} days · sum of daily visitor counts`)}${stat('Successful probes · 24h',checks?(100*passed/checks).toFixed(1)+'%':'—',checks?`${fmt(passed)} of ${fmt(checks)} sampled checks`:'Waiting for the first checks',passed<checks?'stat-warning':'')}${stat('Goals completed',fmt(done),`Marked done during these ${analyticsDays} days`)}</div>`;
 html+=`<div class="grid2 insight-charts"><div class="panel"><div class="panel-header"><div><span class="small-label">DISTRIBUTION</span><h3>Observed download increases</h3></div>${ico('download')}</div>${barChart(growth.dates,'Observed increases between download snapshots')}<p class="caption-line">Only the same release asset is compared. New baselines and reset counters are excluded. Gray marks mean no comparison.${growth.gaps?' Some increases span gaps between observations.':''}</p></div><div class="panel"><div class="panel-header"><div><span class="small-label">AUDIENCE</span><h3>Imported pageviews</h3></div>${ico('chart')}</div>${barChart(growth.dates.map(x=>({date:x.date,value:trafficMap.has(x.date)?trafficMap.get(x.date):null})),'Imported pageviews by day')}<p class="caption-line">${traffic.length?`${new Set(traffic.map(r=>r.date)).size} of ${analyticsDays} dates have imported data. Daily unique visitors are not unique people across the whole period.`:'Import a CSV with date, visitors and pageviews. Meridian does not invent website traffic.'}</p></div></div>`;
 html+=section('Project comparison','Recent default-branch build results and published release assets');
 html+=`<div class="panel table-scroll"><table class="data-table"><thead><tr><th>Project</th><th>Latest release</th><th>Latest asset downloads</th><th>Observed growth · ${analyticsDays}d</th><th>Recent build pass rate</th><th>Open goals</th></tr></thead><tbody>${ps.map(p=>{const g=MeridianMetrics.downloadGrowth(model.download_history,analyticsDays,p.id),b=gh(p).build_stats;return `<tr><td><a href="#${p.id}" class="project-table-name">${esc(p.name)}</a></td><td>${esc(releaseTag(p))}</td><td>${model.download_assets.some(a=>a.project===p.id)?fmt(p.latest_downloads):'—'}</td><td>${g.total===null?'—':'+'+fmt(g.total)}</td><td>${b?.sampled?`${Math.round(100*b.passed/b.sampled)}% <span class="caption-line">(${b.passed}/${b.sampled})</span>`:'—'}</td><td>${fmt(activeGoals(p.id).length)}</td></tr>`;}).join('')}</tbody></table><p class="caption-line">Build rate uses the recent runs returned by GitHub; skipped and cancelled runs are excluded. Downloads are requests, not installations or active users.</p></div>`;
 html+=section('Endpoint reliability','Measured while Meridian is running · last 24 hours');
 html+=`<div class="panel table-scroll"><table class="data-table"><thead><tr><th>Endpoint</th><th>Current check</th><th>Successful checks</th><th>Average response</th><th>Slowest response</th><th>TLS expires</th></tr></thead><tbody>${ps.flatMap(p=>p.sites.map(site=>{const m=probes.find(r=>r.project===p.id&&r.url===site.url),s=site.status;return `<tr><td><strong>${esc(p.name)}</strong><div class="caption-line">${esc(site.label)}</div></td><td>${pill(checkName(sampleTone(s)),sampleTone(s))}</td><td>${m?`${m.passed}/${m.checks}`:'—'}</td><td>${m?.avg_latency_ms!=null?fmt(m.avg_latency_ms)+' ms':'—'}</td><td>${m?.max_latency_ms!=null?fmt(m.max_latency_ms)+' ms':'—'}</td><td>${s?.tls_days!=null?fmt(s.tls_days)+' days':'—'}</td></tr>`;})).join('')}</tbody></table><p class="caption-line">Latency uses successful checks. Missing hours stay unknown; sampled reliability is not continuous uptime. Chart dates use UTC.</p></div>`;
 return html;
}
function runtimePanel(){
 const mode=model.settings?.monitor_mode||'balanced',r=model.runtime||{};
 return `<div class="panel runtime-panel"><div class="panel-header"><div><span class="small-label">DESIGNED TO STAY OPEN</span><h3>Background activity</h3></div>${pill(mode==='paused'?'Paused':mode==='quiet'?'Quiet mode':'Balanced','dim')}</div><div class="mode-options">${[['balanced','Balanced','Sites every 5 min · GitHub every 30 min'],['quiet','Quiet','Sites every 15 min · GitHub every hour'],['paused','Paused','Manual refresh only']].map(([id,name,help])=>`<button data-monitor-mode="${id}" aria-pressed="${mode===id}"><strong>${name}</strong><small>${help}</small></button>`).join('')}</div><div class="runtime-facts"><span>${ico('clock')} Open for ${Math.floor((r.uptime_seconds||0)/3600)}h ${Math.floor((r.uptime_seconds||0)%3600/60)}m</span><span>${ico('server')} Local data ${((r.database_bytes||0)/1048576).toFixed(1)} MB</span><span>${ico('shield')} No dashboard polling while hidden</span></div><p class="caption-line">Fourteen days of endpoint samples and ninety days of download snapshots are retained. Your notes and goals are kept. Release checks continue every six hours in all modes.</p></div>`;
}

function updatePanel(){const u=model.updates||{},status=u.state||'not_checked',has=u.state==='available';const statusText={not_checked:'Not checked yet',unpublished:'Release channel not published',private_or_unpublished:'Private or unpublished channel',not_configured:'Not configured',available:'Update available',up_to_date:'Up to date',error:'Update check unavailable'}[status]||'Unknown';const tone=has?'warn':status==='up_to_date'?'good':'dim';return `<div class="panel" style="margin-bottom:18px"><div class="panel-header"><h3>Meridian updates</h3>${pill(statusText,tone)}</div><div class="keyvalue"><label>Installed version</label><span class="value">v${esc(model.app_version)}</span></div><div class="keyvalue"><label>Release channel</label><span class="value">${esc(u.repository||'Not configured')}</span></div><div class="keyvalue"><label>Last checked</label><span class="value">${esc(u.checked_at?shortDate(u.checked_at):'Not yet checked')}</span></div>${u.latest?`<div class="keyvalue"><label>Latest published version</label><span class="value">v${esc(u.latest)}</span></div>`:''}<p class="caption-line" style="margin:15px 0">${esc(u.detail||'Checks run automatically at startup and every 6 hours while Meridian is running.')}</p><div class="page-actions"><button class="soft-button" data-check-updates>${ico('refresh')} Check now</button>${has&&u.installer_url?`<a class="primary-button" target="_blank" rel="noopener noreferrer" href="${href(u.installer_url)}">${ico('download')} Download for this system</a>`:''}${u.release_url?`<a class="soft-button" target="_blank" rel="noopener noreferrer" href="${href(u.release_url)}">${ico('external')} Release notes</a>`:''}</div><p class="caption-line" style="margin-top:13px">Automatic update checks run at launch and every 6 hours. Windows and Linux desktop notifications appear for new releases when supported. To install, download the verified release package and open it with your software center. Meridian never silently executes an installer, and your local database is preserved.</p></div>`;}
function settingsPage(){return heading('System / preferences','Settings & data','Meridian keeps your private planning information in its local SQLite database.')
 + runtimePanel() + updatePanel() + `<div class="grid2"><div class="panel"><div class="panel-header"><h3>Local data</h3>${pill('Stored on this computer','good')}</div><div class="setting-row"><div><strong>Database directory</strong><p>Your notes, goals, decisions and monitoring history.</p><div class="code-pill">${esc(model.data_dir)}</div></div></div><div class="setting-row"><div><strong>Backup your workspace</strong><p>Export editable planning data and imported visitor analytics as JSON.</p></div><button class="soft-button" data-download-backup>${ico('download')} Export</button></div><div class="setting-row"><div><strong>Restore a backup</strong><p>Replaces your goals, notes, decisions and imported analytics. Does not change GitHub.</p></div><button class="soft-button" data-choose-backup>${ico('upload')} Import</button></div><input hidden type="file" accept="application/json,.json" id="backup-file"/></div><div class="panel"><div class="panel-header"><h3>Automatic monitors</h3>${pill('Local monitoring','dim')}</div><div class="keyvalue"><label>GitHub repositories</label><span class="value">3 public repositories</span></div><div class="keyvalue"><label>Scheduled GitHub refresh</label><span class="value">${model.settings?.monitor_mode==='paused'?'Paused':model.settings?.monitor_mode==='quiet'?'Every hour':'Every 30 minutes'}</span></div><div class="keyvalue"><label>Website probes</label><span class="value">${model.settings?.monitor_mode==='paused'?'Paused':model.settings?.monitor_mode==='quiet'?'Every 15 minutes':'Every 5 minutes'}</span></div><div class="keyvalue"><label>Standalone 24/7 alerts</label><span class="value" style="color:#e1bc7e">Not yet installed</span></div><hr class="divider"/><p class="caption-line">Monitoring runs while Meridian is open. Its data may become stale while the program is closed or your computer is offline.</p></div></div>`
 + section('Connection details','The first version does not require paid services')
 + `<div class="panel"><div class="setting-row"><div><strong>GitHub API</strong><p>Fetches public releases, commits, workflow runs and open issues. Optional environment variable: <code>MERIDIAN_GITHUB_TOKEN</code> for higher rate limits.</p></div>${pill('Public read access','good')}</div><div class="setting-row"><div><strong>Website analytics</strong><p>Import CSV files with daily traffic totals. An authenticated Cloudflare integration is not yet included.</p></div><button class="soft-button" data-modal="analytics">Import CSV</button></div><div class="setting-row"><div><strong>Sundial backup status</strong><p>No authenticated server access is configured. Meridian will never pretend this is monitored.</p></div>${pill('Needs integration','warn')}</div><div class="setting-row"><div><strong>Privacy</strong><p>Meridian does not upload your goals or notes. GitHub queries, website probes and external links make normal outgoing requests.</p></div>${pill('Local-first','good')}</div></div>`;
}
function render(){if(!model)return;current=currentHash();topNav();$('#app-version').textContent=model.app_version;$('#sync-info').innerHTML=`<span class="tiny-pulse ${model.busy?'working':''}"></span>${model.busy?'Syncing sources…':model.settings?.monitor_mode==='paused'?'Monitoring paused':model.settings?.monitor_mode==='quiet'?'Quiet monitoring':'Monitoring active'}`;$('#refresh-button').disabled=!!model.busy;$('#refresh-ico').innerHTML=ico('refresh');let html;switch(current){case 'overview':html=overview();break;case 'latitude':case 'longitude':case 'sundial':html=projectView(project(current));break;case 'activity':html=activityPage();break;case 'analytics':html=analyticsPage();break;case 'settings':html=settingsPage();break;default:html=overview();}$('#page').innerHTML=html;}
async function api(path,options={}){
 const r=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},cache:'no-store',...options});
 if(r.status===401){location.replace('/');throw Error('Your session expired. Sign in again.');}
 const body=await r.json();if(!r.ok)throw Error(body.error||`Request failed (${r.status})`);return body;
}
function schedulePoll(){clearTimeout(pollTimer);if(!document.hidden)pollTimer=setTimeout(()=>load(true),model?.busy?2000:30000);}
async function load(silent=false){
 if(pollBusy)return;pollBusy=true;
 try{
  const r=await fetch('/api/state',{cache:'no-store',headers:stateTag?{'If-None-Match':stateTag}:{}});
  if(r.status===401){location.replace('/');return;}
  if(r.status===304)return;
  const data=await r.json();if(!r.ok)throw Error(data.error||'The local service is unavailable');
  model=data;stateTag=r.headers.get('ETag');
  if(!modalSpec&&!document.querySelector('#prompt-backdrop')){
   const opened=[...document.querySelectorAll('#page details')].map(x=>x.open);
   render();document.querySelectorAll('#page details').forEach((x,i)=>x.open=!!opened[i]);
  }
 }catch(e){
  if(!model)$('#page').innerHTML=`<div class="panel">Cannot reach Meridian: ${esc(e.message)}. <button class="soft-button" data-reconnect>Reconnect</button></div>`;
  else $('#sync-info').textContent='Connection interrupted · retrying';
 }finally{pollBusy=false;schedulePoll();}
}
async function call(path,method,body={}){return api(path,{method,body:JSON.stringify(body)});}
function toast(msg,error=false){const host=$('#toast-root');host.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;setTimeout(()=>{host.innerHTML='';},3500);}
function projectOptions(selected){return Object.keys(labels).map(k=>`<option value="${k}" ${selected===k?'selected':''}>${labels[k]}</option>`).join('');}
function options(items,selected){return items.map(x=>`<option value="${x}" ${selected===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('');}
function field(label,name,value='',type='text',required=false){return `<div class="field"><label for="field-${name}">${label}</label>${type==='textarea'?`<textarea id="field-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`}</div>`;}
function showModal(type,projectId=null,existing=null){modalSpec={type,projectId:projectId||(['latitude','longitude','sundial'].includes(current)?current:'latitude'),existing};let title,subtitle,fields;
 if(type==='goal'){title=existing?'Edit goal':'New goal';subtitle='Write an actionable next step with a clear completion condition.';fields=`<div class="field"><label>Project</label><select name="project" ${existing?'disabled':''}>${projectOptions(existing?.project||modalSpec.projectId)}</select></div>${field('What needs doing?','title',existing?.title,'text',true)}<div class="field-row"><div class="field"><label>Priority</label><select name="priority">${options(['critical','high','medium','low'],existing?.priority||'medium')}</select></div><div class="field"><label>Category</label><input name="category" value="${esc(existing?.category||'General')}"></div></div>${field('Context or completion criteria','description',existing?.description||'','textarea')}<div class="field"><label>Status</label><select name="state">${options(['todo','doing','done'],existing?.state||'todo')}</select></div>`;}
 else if(type==='note'){title='Add a journal note';subtitle='Capture discoveries, outcomes or context that should survive the next session.';fields=`<div class="field"><label>Project</label><select name="project">${projectOptions(modalSpec.projectId)}</select></div>${field('Title','title','','text',true)}${field('What changed / what matters?','body','','textarea',true)}`;}
 else if(type==='decision'){title='Record a decision';subtitle='Keep important constraints and choices visible across coding assistants.';fields=`<div class="field"><label>Project</label><select name="project">${projectOptions(modalSpec.projectId)}</select></div>${field('Decision','title','','text',true)}${field('Reason or tradeoff','reason','','textarea',true)}`;}
 else if(type==='analytics'){title='Import website analytics';subtitle='Import daily totals from your analytics provider. The CSV must include date, visitors and pageviews columns. Import each website separately; existing matching dates will be updated.';fields=`<div class="field"><label>Project</label><select name="project">${projectOptions(modalSpec.projectId)}</select></div><div class="field"><label>CSV file</label><input type="file" id="analytics-file" accept=".csv,text/csv" required></div><div class="caption-line">Example: date,visitors,pageviews &nbsp; / &nbsp; 2026-10-29,24,31</div>`;}
 else return;
 const dom=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-close aria-label="Close dialog">${ico('close')}</button></div><form id="modal-form">${fields}<div class="form-error" id="form-error"></div><div class="modal-footer"><button type="button" class="soft-button" data-close>Cancel</button><button type="submit" class="primary-button">${ico('check')} ${existing?'Save changes':'Save'}</button></div></form></div></div>`;
 $('#modal-root').innerHTML=dom;$('#modal-form input:not([type="file"]),#modal-form select')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';modalSpec=null;render();}
async function saveModal(e){e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]');button.disabled=true;$('#form-error').textContent='';try{const type=modalSpec.type,existing=modalSpec.existing;let payload=Object.fromEntries(new FormData(form).entries());if(type==='analytics'){const file=$('#analytics-file').files?.[0];if(!file)throw Error('Choose a CSV file');payload={project:payload.project,csv:await file.text()};await call('/analytics/import','POST',payload);toast('Analytics imported.');}else if(type==='goal'&&existing){delete payload.project;await call(`/goals/${existing.id}`,'PATCH',payload);toast('Goal updated.');}else{await call(`/${type==='goal'?'goals':type==='note'?'notes':'decisions'}`,'POST',payload);toast('Saved to your local workspace.');}closeModal();await load();}catch(e){$('#form-error').textContent=e.message;button.disabled=false;}}
async function setGoal(id,state){try{await call(`/goals/${id}`,'PATCH',{state});await load(true);toast(state==='done'?'Goal marked complete.':state==='doing'?'Goal started.':'Goal reopened.');}catch(e){toast(e.message,true);}}
async function deleteItem(table,id){const sure=confirm('Delete this item from your local workspace?');if(!sure)return;try{await call(`/${table}/${id}`,'DELETE');await load(true);toast('Item removed.');}catch(e){toast(e.message,true);}}
async function downloadBackup(){try{const data=await api('/backup'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`meridian-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup downloaded.');}catch(e){toast(e.message,true);}}
async function importBackup(file){if(!file)return;const sure=confirm('Restore this backup? Your existing local goals, notes, decisions and imported analytics will be replaced. GitHub history remains.');if(!sure)return;try{const data=JSON.parse(await file.text());await call('/restore','POST',data);await load();toast('Backup restored.');}catch(e){toast(e.message,true);}finally{const el=$('#backup-file');if(el)el.value='';}}
document.addEventListener('click',async e=>{const x=e.target.closest('[data-go],[data-tab],[data-goal-state],[data-edit-goal],[data-delete],[data-modal],[data-close],[data-download-backup],[data-choose-backup],[data-promote],[data-check-updates],[data-toggle-goals],[data-prompt-project]');if(!x){if(e.target.id==='modal-backdrop')closeModal();return;}
 if(x.hasAttribute('data-prompt-project')){await copyRepairPrompt(x.dataset.promptProject,x.dataset.promptGoal?Number(x.dataset.promptGoal):null,x.dataset.promptSite===undefined?null:Number(x.dataset.promptSite));return;}
 if(x.hasAttribute('data-toggle-goals')){const p=x.dataset.toggleGoals;goalExpanded[p]=!goalExpanded[p];render();return;}
 if(x.hasAttribute('data-go')){location.hash=x.dataset.go;return;}
 if(x.hasAttribute('data-tab')){projectTab=x.dataset.tab;render();return;}
 if(x.hasAttribute('data-goal-state')){await setGoal(Number(x.dataset.goalState),x.dataset.state);return;}
 if(x.hasAttribute('data-promote')){const name=x.dataset.promote,p=x.dataset.promoteProject;if(model.goals.some(g=>g.project===p&&g.title===name)){toast('Already in tracked goals.');return;}try{await call('/goals','POST',{project:p,title:name,priority:'medium',category:'From roadmap',description:'Added from GitHub roadmap; completion requires verification.'});await load(true);toast('Roadmap item added to goals.');}catch(e){toast(e.message,true);}return;}
 if(x.hasAttribute('data-edit-goal')){const goal=model.goals.find(g=>g.id===Number(x.dataset.editGoal));if(goal)showModal('goal',goal.project,goal);return;}
 if(x.hasAttribute('data-delete')){await deleteItem(x.dataset.delete,Number(x.dataset.id));return;}
 if(x.hasAttribute('data-modal')){showModal(x.dataset.modal,x.dataset.project||null);return;}
 if(x.hasAttribute('data-close')){closeModal();return;}
 if(x.hasAttribute('data-check-updates')){try{const r=await call('/updates/check','POST');toast(r.started?'Checking Meridian releases…':'An update check is already running.');setTimeout(()=>load(true),1600);}catch(e){toast(e.message,true);}return;}
 if(x.hasAttribute('data-download-backup')){downloadBackup();return;}
 if(x.hasAttribute('data-choose-backup')){$('#backup-file')?.click();return;}
});
document.addEventListener('click',e=>{const close=e.target.closest('[data-close-prompt]'),select=e.target.closest('[data-select-prompt]');if(close||e.target.id==='prompt-backdrop')document.querySelector('#prompt-backdrop')?.remove();if(select){const t=document.querySelector('#prompt-backdrop textarea');t?.focus();t?.select();}},true);
document.addEventListener('submit',e=>{if(e.target.id==='modal-form')saveModal(e);});
document.addEventListener('change',e=>{if(e.target.id==='backup-file')importBackup(e.target.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalSpec){closeModal();return;}if(e.key==='Enter'&&e.target.classList.contains('project-card'))location.hash=e.target.dataset.go;});
window.addEventListener('hashchange',()=>{projectTab='plan';render();window.scrollTo(0,0);});
$('#refresh-button').addEventListener('click',async()=>{try{const r=await call('/refresh','POST',{kind:'all'});toast(r.started?'Refreshing GitHub and sites…':'A refresh is already in progress.');await load(true);}catch(e){toast(e.message,true);}});
$('#lock-button').addEventListener('click',async()=>{try{await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});}finally{location.replace('/');}});
$('#menu-toggle').innerHTML=ico('menu');
document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('is-hidden',document.hidden);clearTimeout(pollTimer);if(!document.hidden)load(true);});
window.addEventListener('pagehide',()=>clearTimeout(pollTimer));
window.addEventListener('focus',()=>{if(!document.hidden)load(true);});
current=currentHash();load();

document.addEventListener('click',async e=>{
 if(e.target.closest('[data-reconnect]')){stateTag=null;load();}
 const mode=e.target.closest('[data-monitor-mode]');if(mode){
  try{await call('/settings/monitoring','POST',{mode:mode.dataset.monitorMode});await load(true);toast('Monitoring preference saved.');}catch(err){toast(err.message,true);}
 }
 const days=e.target.closest('[data-analytics-days]');if(days){analyticsDays=Number(days.dataset.analyticsDays);render();}
});
document.addEventListener('change',e=>{if(e.target.id==='analytics-project'){analyticsProject=e.target.value;render();}});
